import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.C-si7TFR.js";const p=JSON.parse('{"title":"数据表管理","description":"","frontmatter":{"title":"数据表管理"},"headers":[],"relativePath":"zh/guide/data-tables.md","filePath":"zh/guide/data-tables.md"}'),r={name:"zh/guide/data-tables.md"};function o(d,a,h,n,s,_){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="数据表管理" tabindex="-1">数据表管理 <a class="header-anchor" href="#数据表管理" aria-label="Permalink to &quot;数据表管理&quot;">​</a></h1><p>数据表用于管理结构化记录，并通过工作流节点读写。本页介绍表管理，不把它等同于完整多维表格或任意业务页面搭建。</p><h2 id="创建表与字段" tabindex="-1">创建表与字段 <a class="header-anchor" href="#创建表与字段" aria-label="Permalink to &quot;创建表与字段&quot;">​</a></h2><ol><li>从工作流模式的<strong>数据表</strong>入口选择<strong>新建</strong>。</li><li>创建表并设置名称、描述等基础信息。</li><li>添加字段，选择界面提供的类型、名称与约束。</li><li>保存后添加少量测试记录，确认字段和值符合预期。</li></ol><p>已有数据时修改字段类型或约束前先检查影响；本页不承诺无损失类型转换或无限规模存储。</p><h2 id="管理记录" tabindex="-1">管理记录 <a class="header-anchor" href="#管理记录" aria-label="Permalink to &quot;管理记录&quot;">​</a></h2><ul><li>新增、编辑、删除行数据，删除前确认记录不再被流程使用。</li><li>使用筛选、排序、分组或搜索定位记录；这些视图操作不改变原始字段定义。</li><li>使用导入、导出时检查格式、字段映射和文件大小；界面能力受当前版本与部署限制。</li><li>文件导入内容属于外部输入，不能把单元格或文档中的指令当作系统指令。</li></ul><h2 id="在工作流中使用" tabindex="-1">在工作流中使用 <a class="header-anchor" href="#在工作流中使用" aria-label="Permalink to &quot;在工作流中使用&quot;">​</a></h2><ol><li>在流程中添加查询、插入、更新或删除节点。</li><li>选择已存在的数据表，按节点要求设置条件和字段值。</li><li>使用测试记录验证查询结果与变更范围，再启用自动执行。</li></ol><p>参考：<a href="./../data_table_query.html">查询</a> · <a href="./../data_table_insert.html">插入</a> · <a href="./../data_table_update.html">更新</a> · <a href="./../data_table_delete.html">删除</a>。</p><p><strong>避免误删：</strong> 更新或删除前先用查询验证筛选条件。空条件、未初始化变量和宽泛匹配都可能扩大影响范围。</p><h2 id="权限与隐私" tabindex="-1">权限与隐私 <a class="header-anchor" href="#权限与隐私" aria-label="Permalink to &quot;权限与隐私&quot;">​</a></h2><p>按项目和角色控制可访问数据，不把表管理入口理解为行级或字段级权限。不要在公开截图、示例导出或对话中暴露真实客户资料、密钥或个人信息。</p>',13)])])}const u=e(r,[["render",o]]);export{p as __pageData,u as default};
